def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    earlier = {"id": "a", "day": 5, "flagged": True}
    latest = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    first_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([earlier, same_day, first_day, latest]) == [
        first_day, latest, same_day
    ]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range():
